// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;

import "./IBEP20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract Betting is Initializable{

    uint DEVELOPER_COMMISSION;
    uint DEVELOPER_COMMISSION_BALANCE;
    uint PLATFORM_COMMISSION;
    uint PLATFORM_COMMISSION_BALANCE;
    address ADMIN_FIRST;
    address ADMIN_SECOND;
    IBEP20 public ASSET;

    struct Stake{
        address payable owner;
        string matchId;
        uint amount;
        string team; //should be team id
        string odd;  // either win, loose or draw
        bool withdrawn;
        // bool won;
    }

    struct Game{
        string id;
        string teamA;
        string teamB;
        uint startTime;
        uint totalStakes;
        uint teamAStakes;
        uint drawStakes;
        uint teamBStakes;
        string winner;
        string looser;
        bool draw;
        bool ended;
    }

    modifier onlyAdmin{
        require(msg.sender == ADMIN_FIRST ||msg.sender == ADMIN_SECOND,"Unauthorized to make transaction");
        _;
    }

    event Staked(string stakeId,uint amout,address user);
    event GameCreated(string gameId);
    event ScoreUpdated(string gameId,string winner, string looser,bool isDraw);
    event FundsWithdrawn(string stakeId);
    event StakeAdded(string stakeId, uint amount);
    event FirstAdminChanged(address oldAdmin,address newAdmin);
    event SecondAdminChanged(address oldAdmin,address newAdmin);
    event DeveloperCommissionChanged(uint newPercentage);
    event PlatformCommissionChanged(uint newPercentage);
    event DeveloperFeeWithdrawn(address admin,uint amount);
    event PlatformFeeWithdrawn(address admin,uint amount);


    // stake id
    mapping(string=>Stake) public Stakes;
    //  game id
    mapping(string=>Stake[]) public StakesOfGame;
    // game id
    mapping(string=>Game) public Games;



    function initialize(address _admin_a,address _admin_b,address _asset) initializer public{
        ADMIN_FIRST = _admin_a;
        ADMIN_SECOND = _admin_b;
        PLATFORM_COMMISSION = 5/uint(100);
        DEVELOPER_COMMISSION = 5/uint(100);
        DEVELOPER_COMMISSION_BALANCE = 0;
        PLATFORM_COMMISSION_BALANCE = 0;
        ASSET = IBEP20(_asset);
    }



    function hashOf(string memory _str) pure private returns(bytes32){
        return keccak256(abi.encodePacked(_str));
    }



    function calculatePercentage(uint _bit, uint _total) pure public returns(uint){
        return ((_bit * 100)/_total);
    }


    function createGame(string memory _gameId,string memory _teamA,string memory _teamB,uint _startTime) external onlyAdmin{
        require(block.timestamp < _startTime,"Too Early");
        Games[_gameId] = Game(_gameId,_teamA,_teamB,_startTime,0,0,0,0,"","",false,false);
        emit GameCreated(_gameId);
    }

    function setFirstAdmin(address _newAdmin) external onlyAdmin{
      address _oldAdmin = ADMIN_FIRST;
      ADMIN_FIRST = _newAdmin;
      emit FirstAdminChanged(_oldAdmin,_newAdmin);
    }

    function setSecondAdmin(address _newAdmin) external onlyAdmin{
      address _oldAdmin = ADMIN_SECOND;
      ADMIN_SECOND = _newAdmin;
      emit FirstAdminChanged(_oldAdmin,_newAdmin);
    }
    //should be an interger like 5 => 5% or 10 =>10%
    function setDeveloperCommision(uint _percentage) external onlyAdmin{
      require(_percentage < uint(100),"invalid percentage");
      DEVELOPER_COMMISSION = _percentage/uint(100);
      emit DeveloperCommissionChanged((_percentage/uint(100)));
    }
    //should be an interger like 5 => 5% or 10 =>10%
    function setPlatformCommision(uint _percentage) external onlyAdmin{
      require(_percentage < uint(100),"invalid percentage");
      PLATFORM_COMMISSION = _percentage/uint(100);
      emit PlatformCommissionChanged((_percentage/uint(100)));
    }

    function updateScore(string memory _gameId,string memory _winner, string memory _looser, bool _isDraw) external payable onlyAdmin{
        Game storage __game = Games[_gameId];
        __game.winner = _winner;
        __game.looser = _looser;
        __game.draw = _isDraw;
        __game.ended == true;
        emit ScoreUpdated(_gameId, _winner, _looser, _isDraw);
    }

    function withdrawPlatformFee(uint _amount) external onlyAdmin{
      require(_amount <= PLATFORM_COMMISSION_BALANCE,"insufficient amount");
      PLATFORM_COMMISSION_BALANCE -= _amount;
      IBEP20(ASSET).transfer(payable(msg.sender),_amount);
      emit PlatformFeeWithdrawn(msg.sender,_amount);
    }

    function withdrawDeveloperFee(uint _amount) external onlyAdmin{
      require(_amount <= DEVELOPER_COMMISSION_BALANCE,"insufficient amount");
      DEVELOPER_COMMISSION_BALANCE -= _amount;
      IBEP20(ASSET).transfer(payable(msg.sender),_amount);
      emit DeveloperFeeWithdrawn(msg.sender,_amount);
    }

    function getPlatformBalance()external onlyAdmin view returns(uint){
      return PLATFORM_COMMISSION_BALANCE;
    }

    function getDeveloperBalance()external onlyAdmin view returns(uint){
      return DEVELOPER_COMMISSION_BALANCE;
    }

    function createStake(string memory _stakeId,string memory _gameId,uint _stakeAmount, string memory _team, string memory _odd) payable external {
        require(_stakeAmount > 0,"you have to stake a fee");
        Game storage game = Games[_gameId];
        require(block.timestamp < game.startTime,"too late to stake");
        //this makes sure user doesnt upload invalid team
        require(hashOf(_team) == hashOf(game.teamA) || hashOf(_team) == hashOf(game.teamB),"Invalid team");
        Stakes[_stakeId] = Stake(payable(msg.sender),_gameId,_stakeAmount,_team,_odd,false);
        if(hashOf(_team) == hashOf(game.teamA)){
            game.teamAStakes += _stakeAmount;
        }else if(hashOf(_team) == hashOf(game.teamB)){
            game.teamBStakes += _stakeAmount;
        }else if(hashOf(_odd) == hashOf("draw")){
          game.drawStakes += _stakeAmount;
        }
        IBEP20(ASSET).transferFrom(msg.sender,address(this), _stakeAmount);
        emit Staked(_stakeId,_stakeAmount,msg.sender);
    }


    function checkIsWinner(string memory _stakeId) public view returns (bool){
        Stake memory _stake = Stakes[_stakeId];
        require(msg.sender == _stake.owner,"Unauthorized to make check");
        Game memory _game = Games[_stake.matchId];
        require(_game.ended == true,"Match results still unavailable");
        if(_game.draw == true && (hashOf(_stake.odd) == hashOf("draw"))){
            return true;
        }
        if(hashOf(_stake.odd) == hashOf("win") && (hashOf(_stake.team) == hashOf(_game.winner))){
            return true;
        }
        if(hashOf(_stake.odd) == hashOf("loose") && (hashOf(_stake.team) == hashOf(_game.looser))){
            return true;
        }
        return false;
    }



    function calculateDividend( string memory _stakeId) public view returns(uint){
        Stake memory __stake = Stakes[_stakeId];
        Game memory __game = Games[__stake.matchId];
        require((__stake.owner == msg.sender) || (__stake.owner == ADMIN_FIRST || __stake.owner == ADMIN_SECOND) ,"Unauthorized to make this transaction");
        bool flag;
        uint _totalTeamStakes;
        uint _totalOtherTeamStakes;
        if(hashOf(__stake.team) == hashOf(__game.teamA)){
            flag = true;
            _totalTeamStakes = __game.teamAStakes;
            _totalOtherTeamStakes = __game.teamBStakes + __game.drawStakes;
        }else if(hashOf(__stake.team) == hashOf(__game.teamB)){
            flag = true;
            _totalTeamStakes = __game.teamBStakes;
            _totalOtherTeamStakes = __game.teamAStakes + __game.drawStakes;
        }
        require(flag == true, "Invalid team");
        uint _percentage = calculatePercentage(__stake.amount,_totalTeamStakes);
        return (_percentage * _totalOtherTeamStakes);
    }


    function withrawFund(string memory _stakeId) external {
        Stake storage _stake = Stakes[_stakeId];
        require(msg.sender == _stake.owner,"Unauthorized to make withdrawal");
        require(_stake.withdrawn == false, "Funds withdrawn already");
        Game storage _game = Games[_stake.matchId];
        require(_game.ended == true, "too early to withdraw");
        (bool _isWinner) = checkIsWinner(_stakeId);
        require(_isWinner == true,"you lost the match");
        (uint _reward) = calculateDividend(_stakeId);
        uint _totalDividend = uint(_reward + _stake.amount);
        _game.totalStakes -= _totalDividend;
        _stake.withdrawn = true;
        uint COMMISSIONS = uint(DEVELOPER_COMMISSION + PLATFORM_COMMISSION);
        uint COMMISSION_PERCENTAGE = calculatePercentage((COMMISSIONS * 100),_totalDividend);
        uint COMMISSION_FEE = uint(COMMISSION_PERCENTAGE * _totalDividend);
        uint amountToBeWithdrawn = uint(_totalDividend - COMMISSION_FEE);
        uint _developerCommission = calculatePercentage(DEVELOPER_COMMISSION,COMMISSION_FEE);
        uint _platformCommission = calculatePercentage(PLATFORM_COMMISSION,COMMISSION_FEE);
        DEVELOPER_COMMISSION_BALANCE += uint(_developerCommission * COMMISSION_FEE);
        PLATFORM_COMMISSION_BALANCE += uint(_platformCommission * COMMISSION_FEE);
        IBEP20(ASSET).transfer(payable(msg.sender), amountToBeWithdrawn);
        emit FundsWithdrawn(_stakeId);
    }


    receive() external payable{}


    function addStake(string memory _stakeId,uint _amount)payable public{
        Stake storage _stake = Stakes[_stakeId];
        require(msg.sender == _stake.owner,"Unauthorized to make transaction");
        Game storage _game = Games[_stake.matchId];
        require(_game.startTime > block.timestamp,"Match started already");
        _stake.amount += _amount;
        if(hashOf(_stake.team) == hashOf(_game.teamA)){
            _game.teamAStakes += _amount;
        }else{
            _game.teamBStakes += _amount;
        }
        _game.totalStakes += _amount;
        IBEP20(ASSET).transferFrom(msg.sender, address(this),_amount);
        emit StakeAdded(_stakeId,_amount);
    }

    function removeStake(string memory _stakeId)public{
        Stake storage _stake = Stakes[_stakeId];
        require(msg.sender == _stake.owner,"Unauthorized to make transaction");
        Game storage _game = Games[_stake.matchId];
        require(_game.startTime > block.timestamp,"game started already");
        uint _amountStaked = _stake.amount;
        if(hashOf(_stake.team) == hashOf(_game.teamA)){
            _game.teamAStakes -= _amountStaked;
        }else{
            _game.teamBStakes += _amountStaked;
        }
        _stake.amount = 0;
        _game.totalStakes -= _amountStaked;
        IBEP20(ASSET).transfer(payable(msg.sender), _amountStaked);
    }

}
